'use client';

// Alert sounds generated by code with the Web Audio API (vol. 07 §6): no audio file to source or
// license. Browsers require a user interaction first ("Démarrer le service").

let context: AudioContext | null = null;

export function unlockAudio(): boolean {
  try {
    context ??= new AudioContext();
    if (context.state === 'suspended') void context.resume();
    return true;
  } catch {
    return false;
  }
}

function tone(frequency: number, start: number, duration: number, volume: number, type: OscillatorType = 'sine') {
  if (!context) return;
  const osc = context.createOscillator();
  const gain = context.createGain();
  osc.type = type;
  osc.frequency.value = frequency;
  gain.gain.setValueAtTime(0, context.currentTime + start);
  gain.gain.linearRampToValueAtTime(volume, context.currentTime + start + 0.02);
  gain.gain.exponentialRampToValueAtTime(0.0001, context.currentTime + start + duration);
  osc.connect(gain).connect(context.destination);
  osc.start(context.currentTime + start);
  osc.stop(context.currentTime + start + duration + 0.05);
}

/** New order to validate: short, clear two-note chime, distinct from a phone notification. */
export function playNewOrderChime(): void {
  tone(880, 0, 0.35, 0.35);
  tone(1318.5, 0.18, 0.5, 0.3);
}

/** Order late in the kitchen (red): low, brief sound, once per order. */
export function playLateSound(): void {
  tone(196, 0, 0.6, 0.4, 'triangle');
}

let wakeLock: { release: () => Promise<void> } | null = null;

/** Keeps the screen on during the service (Screen Wake Lock API). */
export async function keepScreenOn(): Promise<void> {
  try {
    const nav = navigator as Navigator & { wakeLock?: { request: (t: 'screen') => Promise<{ release: () => Promise<void> }> } };
    wakeLock = (await nav.wakeLock?.request('screen')) ?? null;
  } catch {
    wakeLock = null;
  }
}

export function screenIsKeptOn(): boolean {
  return wakeLock !== null;
}
